    """Load HSK words up to the given level (1-5).

    Args:
        max_level: Highest HSK level to include (1-5).

    Returns:
        Set of Chinese words from HSK 1 through max_level.
    """
    if not 1 <= max_level <= 5:
        raise ValueError(f"max_level must be 1-5, got {max_level}")
    result: set[str] = set()
    for level in range(1, max_level + 1):
        result |= _LEVELS[level]
    return result
